mapper.select:
SELECT d.dept_name AS deptName, MAX(avg_usage) AS avgUsage, MAX(am_usage) AS amUsage, MAX(pm_usage) AS pmUsage, MAX(holiday_usage) AS holidayUsage FROM TR_ROOM_USE_DTL r INNER JOIN TR_DEPT_DICT d ON r.dept_code = d.dept_code WHERE r.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY d.dept_name ORDER BY d.dept_name
